def read_source(path: Path) -> str:
    try:
        return (WORKSPACE_ROOT / path).read_text(encoding="utf-8")
    except OSError as exc:
        fail(GATE_NAME, f"failed to read {path.as_posix()}: {exc}")


def check_source(check: SourceCheck, failures: list[str]) -> None:
    source = "\n".join(
        [read_source(check.path), *(read_source(path) for path in check.extra_paths)]
    )
    for marker in check.required:
        if marker not in source:
            failures.append(f"{check.path.as_posix()}: missing {marker}")
    for marker in check.forbidden:
        if marker in source:
            failures.append(f"{check.path.as_posix()}: forbidden {marker}")


def find_struct_body(source: str, struct_name: str) -> str | None:
    match = re.search(rf"\bpub\s+struct\s+{re.escape(struct_name)}(?:<[^>]+>)?\s*\{{", source)
    if match is None:
        return None

    start = match.end()
    depth = 1
    idx = start
    while idx < len(source):
        char = source[idx]
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return source[start:idx]
        idx += 1
    return None


def public_opaque_struct_names(source: str) -> list[str]:
    names: list[str] = []
    for match in re.finditer(
        r"\bpub\s+struct\s+([A-Za-z_][A-Za-z0-9_]*)(?:\s*<[^{};]+>)?\s*\{",
        source,
    ):
        name = match.group(1)
        if name.endswith(OPAQUE_STRUCT_SUFFIXES):
            names.append(name)
    return names


def check_opaque_struct_catalog(
    checks: list[OpaqueStructCheck], failures: list[str]
) -> None:
    covered: dict[Path, set[str]] = {}
    for check in checks:
        covered.setdefault(check.path, set()).update(check.struct_names)

    for root in OPAQUE_STRUCT_SCAN_ROOTS:
        scan_root = WORKSPACE_ROOT / root
        if not scan_root.exists():
            failures.append(f"{root.as_posix()}: missing opaque-struct scan root")
            continue

        for source_path in sorted(scan_root.rglob("*.rs")):
            path = source_path.relative_to(WORKSPACE_ROOT)
            source = read_source(path)
            for struct_name in public_opaque_struct_names(source):
                if struct_name not in covered.get(path, set()):
                    failures.append(
                        f"{path.as_posix()} {struct_name}: public opaque struct is not covered by opaque-struct check"
                    )


def check_opaque_structs(check: OpaqueStructCheck, failures: list[str]) -> None:
    source = read_source(check.path)
    for struct_name in check.struct_names:
        body = find_struct_body(source, struct_name)
        if body is None:
            failures.append(f"{check.path.as_posix()}: missing public struct {struct_name}")
            continue
        for line_no, line in enumerate(body.splitlines(), start=1):
            stripped = line.strip()
            if re.match(r"^pub\s+[A-Za-z_][A-Za-z0-9_]*\s*:", stripped):
                failures.append(
                    f"{check.path.as_posix()} {struct_name}: public field still exposed: {stripped}"
                )


def dependency_section(source: str, section: str) -> str:
    marker = f"[{section}]"
    start = source.find(marker)
    if start == -1:
        return ""
    body_start = start + len(marker)
    next_section = source.find("\n[", body_start)
    if next_section == -1:
        return source[body_start:]
    return source[body_start:next_section]


def check_fret_imui_runtime_dependencies(failures: list[str]) -> None:
    path = Path("ecosystem/fret-imui/Cargo.toml")
    source = read_source(path)
    deps = dependency_section(source, "dependencies")
    required = [
        "fret-authoring = { path = \"../fret-authoring\" }",
        "fret-ui = { path = \"../../crates/fret-ui\" }",
    ]
    forbidden = [
        "fret-ui-kit",
        "fret-ui-editor",
        "fret-docking",
        "fret-plot",
        "fret-chart",
        "fret-workspace",
        "fret-ui-shadcn",
        "winit",
        "wgpu",
    ]
    for marker in required:
        if marker not in deps:
            failures.append(f"{path.as_posix()} [dependencies]: missing {marker}")
    for marker in forbidden:
        if marker in deps:
            failures.append(f"{path.as_posix()} [dependencies]: forbidden {marker}")


def check_imui_direct_text_props_allowlist(failures: list[str]) -> None:
    check_direct_text_props_allowlist(
        Path("ecosystem/fret-ui-kit/src/imui"),
        IMUI_DIRECT_TEXT_PROPS_ALLOWED,
        "IMUI",
        failures,
    )


def check_direct_text_props_allowlist(
    root: Path,
    allowed_by_path: dict[Path, dict[str, int]],
    label: str,
    failures: list[str],
) -> None:
    actual: dict[Path, dict[str, int]] = {}
    scan_root = WORKSPACE_ROOT / root
    if not scan_root.exists():
        failures.append(f"{root.as_posix()}: missing {label} text-props scan root")
        return

    for source_path in sorted(scan_root.rglob("*.rs")):
        path = source_path.relative_to(WORKSPACE_ROOT)
        source = read_source(path)
        for line in source.splitlines():
            stripped = line.strip()
            is_text_props_constructor = "TextProps::new(" in stripped or (
                "TextProps {" in stripped and "-> TextProps {" not in stripped
            )
            if not is_text_props_constructor:
                continue
            actual.setdefault(path, {})
            actual[path][stripped] = actual[path].get(stripped, 0) + 1

    for path, constructors in sorted(actual.items()):
        allowed = allowed_by_path.get(path)
        if allowed is None:
            for constructor, count in sorted(constructors.items()):
                failures.append(
                    f"{path.as_posix()}: direct TextProps construction is not in the {label} text-role allowlist ({count}x {constructor})"
                )
            continue
        for constructor, count in sorted(constructors.items()):
            expected = allowed.get(constructor)
            if expected is None:
                failures.append(
                    f"{path.as_posix()}: direct TextProps construction is not allowed by the {label} allowlist: {constructor}"
                )
            elif count != expected:
                failures.append(
                    f"{path.as_posix()}: direct TextProps construction count changed for {constructor}: expected {expected}, found {count}"
                )

    for path, constructors in sorted(allowed_by_path.items()):
        actual_for_path = actual.get(path, {})
        for constructor, expected in sorted(constructors.items()):
            count = actual_for_path.get(constructor, 0)
            if count != expected:
                failures.append(
                    f"{path.as_posix()}: missing allowed direct TextProps construction {constructor}: expected {expected}, found {count}"
                )


def check_property_row_value_slot_overflow(failures: list[str]) -> None:
    paths = [
        Path("ecosystem/fret-ui-editor/src/composites/property_row/element.rs"),
        Path("ecosystem/fret-ui-editor/src/composites/property_row/element/row.rs"),
        Path("ecosystem/fret-ui-editor/src/composites/property_row/element/column.rs"),
    ]
    marker = "let value = mark_property_row_value_slot(cx.container("
    matches: list[tuple[Path, str, int]] = []
    for path in paths:
        source = read_source(path)
        matches.extend(
            (path, source, match.start()) for match in re.finditer(re.escape(marker), source)
        )
    if len(matches) != 2:
        failures.append(
            "property-row value slots: expected exactly two marked slots across element owners, "
            f"found {len(matches)}"
        )

    for path, source, start in matches:
        end = source.find("|cx| vec![value(cx)]", start)
        if end == -1:
            failures.append(
                f"{path.as_posix()}: property-row value slot marker is missing its value-child closure"
            )
            continue
        block = source[start:end]
        if "overflow: Overflow::Clip" in block:
            failures.append(
                f"{path.as_posix()}: property-row value slot must not clip wrapping value/prose children"
            )


def check_table_column_accessors(failures: list[str]) -> None:
    path = Path("ecosystem/fret-ui-kit/src/imui/options/collections/table_column.rs")
    source = read_source(path)
    body = find_struct_body(source, "TableColumn")
    if body is None:
        failures.append(f"{path.as_posix()}: missing public struct TableColumn")
    else:
        for field in (
            "header",
            "id",
            "width",
            "visible",
            "sortable",
            "sort_direction",
            "resize",
            "pin",
        ):
            if re.search(rf"^\s*pub(?:\([^)]+\))?\s+{field}\s*:", body, re.MULTILINE):
                failures.append(
                    f"{path.as_posix()} TableColumn: field must stay private/accessor-first: {field}"
                )

    accessor_sources = {
        "identity": read_source(
            Path("ecosystem/fret-ui-kit/src/imui/options/collections/table_column/identity.rs")
        ),
        "visibility": read_source(
            Path("ecosystem/fret-ui-kit/src/imui/options/collections/table_column/visibility.rs")
        ),
        "sorting": read_source(
            Path("ecosystem/fret-ui-kit/src/imui/options/collections/table_column/sorting.rs")
        ),
        "resize": read_source(
            Path("ecosystem/fret-ui-kit/src/imui/options/collections/table_column/resize.rs")
        ),
        "pinning": read_source(
            Path("ecosystem/fret-ui-kit/src/imui/options/collections/table_column/pinning.rs")
        ),
    }
    for owner, marker in (
        ("identity", "pub fn header(&self) -> Option<&str>"),
        ("identity", "pub(crate) fn header_arc(&self) -> Option<Arc<str>>"),
        ("identity", "pub fn id(&self) -> Option<&str>"),
        ("identity", "pub(crate) fn id_arc(&self) -> Option<Arc<str>>"),
        ("identity", "pub fn width(&self) -> super::TableColumnWidth"),
        ("visibility", "pub fn visible(&self) -> bool"),
        ("visibility", "pub(crate) fn set_visible_for_policy(&mut self, visible: bool)"),
        ("sorting", "pub fn is_sortable(&self) -> bool"),
        ("sorting", "pub fn sort_direction(&self) -> Option<TableSortDirection>"),
        ("resize", "pub fn resize_options(&self) -> Option<TableColumnResizeOptions>"),
        ("pinning", "pub fn pin(&self) -> TableColumnPin"),
    ):
        if marker not in accessor_sources[owner]:
            failures.append(
                f"{path.as_posix()}: missing TableColumn {owner} accessor seam {marker}"
            )


